import{_ as i,o as a,c as t,a4 as e}from"./chunks/framework.vNSRaLQv.js";const c=JSON.parse('{"title":"CC Switch 显示错误模型名的排查与解决","description":"","frontmatter":{"title":"CC Switch 显示错误模型名的排查与解决","date":"2026-06-14T00:00:00.000Z"},"headers":[],"relativePath":"posts/ccswitch-model-name-bug.md","filePath":"posts/ccswitch-model-name-bug.md"}'),h={name:"posts/ccswitch-model-name-bug.md"};function l(n,s,p,d,k,o){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="cc-switch-显示错误模型名的排查与解决" tabindex="-1">CC Switch 显示错误模型名的排查与解决 <a class="header-anchor" href="#cc-switch-显示错误模型名的排查与解决" aria-label="Permalink to &quot;CC Switch 显示错误模型名的排查与解决&quot;">​</a></h1><h2 id="问题描述" tabindex="-1">问题描述 <a class="header-anchor" href="#问题描述" aria-label="Permalink to &quot;问题描述&quot;">​</a></h2><p>我用 CC Switch + 自建代理（DeepSeek Web Agent Proxy）给 Claude Code 做中转，代理后端是通义千问（Qwen）。代理本身没问题 — 响应里每个 SSE chunk 都返回 <code>&quot;model&quot;: &quot;qwen3.7-max&quot;</code>，但 CC Switch 的用量面板里一直显示 <code>claude-opus-4-8</code>。</p><p>其他中转站没这个问题，只有自建代理会出现。</p><h2 id="排查过程" tabindex="-1">排查过程 <a class="header-anchor" href="#排查过程" aria-label="Permalink to &quot;排查过程&quot;">​</a></h2><h3 id="_1-确认代理侧没问题" tabindex="-1">1. 确认代理侧没问题 <a class="header-anchor" href="#_1-确认代理侧没问题" aria-label="Permalink to &quot;1. 确认代理侧没问题&quot;">​</a></h3><p>抓包确认，我们代理的响应<strong>每个 chunk 都带了正确的 model</strong>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">data: </span><span style="--shiki-light:#999999;--shiki-dark:#666666;">{</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">id</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">...</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">object</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">chat.completion.chunk</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">model</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">qwen3.7-max</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">choices</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:[</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">],</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">usage</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:{</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">}}</span></span></code></pre></div><p>非流式响应也一样：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#999999;--shiki-dark:#666666;">{</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">id</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">...</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">model</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">qwen3.7-max</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">,</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">choices</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:[</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">],</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">usage</span><span style="--shiki-light:#99841877;--shiki-dark:#B8A96577;">&quot;</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:{</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">}}</span></span></code></pre></div><p>响应 100% 正确，问题不在我们这边。</p><h3 id="_2-查-cc-switch-日志" tabindex="-1">2. 查 CC Switch 日志 <a class="header-anchor" href="#_2-查-cc-switch-日志" aria-label="Permalink to &quot;2. 查 CC Switch 日志&quot;">​</a></h3><p>翻 CC Switch 的日志文件 <code>~/.cc-switch/logs/cc-switch.log</code>，发现转发时 model 已经被正确替换了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>[Claude] &gt;&gt;&gt; 请求 URL: http://127.0.0.1:48391/v1/chat/completions (model=qwen3.7-max)</span></span></code></pre></div><p>日志显示 CC Switch <strong>知道</strong>实际转发的是 <code>qwen3.7-max</code>。</p><h3 id="_3-查-cc-switch-数据库" tabindex="-1">3. 查 CC Switch 数据库 <a class="header-anchor" href="#_3-查-cc-switch-数据库" aria-label="Permalink to &quot;3. 查 CC Switch 数据库&quot;">​</a></h3><p>CC Switch 用 SQLite 存请求日志。查 <code>proxy_request_logs</code> 表：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">SELECT</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> model, request_model </span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">FROM</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> proxy_request_logs </span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">WHERE</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> app_type</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">=</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&#39;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">claude</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&#39;</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;"> ORDER BY</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> created_at </span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">DESC</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;"> LIMIT</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 5</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">;</span></span></code></pre></div><p>结果：</p><table tabindex="0"><thead><tr><th>model</th><th>request_model</th></tr></thead><tbody><tr><td>claude-opus-4-8</td><td>claude-opus-4-8</td></tr><tr><td>claude-opus-4-8</td><td>claude-opus-4-8</td></tr><tr><td>claude-opus-4-8</td><td>claude-opus-4-8</td></tr></tbody></table><p><code>model</code> 和 <code>request_model</code> 都是 <code>claude-opus-4-8</code>。CC Switch 转发时用了 <code>qwen3.7-max</code>，但<strong>写数据库时没记录转发后的 model</strong>。</p><h3 id="_4-定位根因" tabindex="-1">4. 定位根因 <a class="header-anchor" href="#_4-定位根因" aria-label="Permalink to &quot;4. 定位根因&quot;">​</a></h3><p>搜 CC Switch 的 GitHub Issues，找到了 <a href="https://github.com/farion1231/cc-switch/issues/3846" target="_blank" rel="noreferrer">Issue #3846</a>：</p><blockquote><p><strong>Bug: Streaming timeout causes wrong model name and zero tokens in usage logs</strong></p><p>当流式响应的 model 提取失败时，<code>claude_model_extractor</code> 回退到 <code>request_model</code>（请求体的原始 model）。</p></blockquote><p>根本原因在 CC Switch 的 Rust 代码里。CC Switch 做 Anthropic → OpenAI 格式转换时，转发器会把 model 替换成配置的模型名（<code>qwen3.7-max</code>），但<strong>写数据库的 usage 收集器</strong>从 SSE 事件中提取 model 名时失败了，回退到了 <code>request_model</code>（Claude Code 发过来的 <code>claude-opus-4-8</code>）。</p><p>流程是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Claude Code 发请求 → body.model = &quot;claude-opus-4-8&quot;</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>CC Switch 转发 → 替换为 model = &quot;qwen3.7-max&quot;，发给我们的代理</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>我们的代理返回 → 响应 model = &quot;qwen3.7-max&quot;（正确）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>CC Switch 收到响应 → 转回 Anthropic 格式给 Claude Code</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>CC Switch 写数据库 → model_extractor 从 SSE 事件中提取 model 失败</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>回退到 request_model = &quot;claude-opus-4-8&quot;（错误）</span></span></code></pre></div><h3 id="_5-为什么其他中转站没问题" tabindex="-1">5. 为什么其他中转站没问题？ <a class="header-anchor" href="#_5-为什么其他中转站没问题" aria-label="Permalink to &quot;5. 为什么其他中转站没问题？&quot;">​</a></h3><p>其他中转站（如 pie-xian）用的是 <strong>Anthropic 原生格式</strong>（<code>apiFormat: &quot;anthropic&quot;</code>），CC Switch 不需要做格式转换，直接透传。这种情况下 model 提取是正常的。</p><p>我们用的是 <strong>OpenAI Chat Completions 格式</strong>（<code>apiFormat: &quot;openai_chat&quot;</code>），CC Switch 需要做 Anthropic ↔ OpenAI 的双向转换。格式转换路径上的 model 提取逻辑有 bug。</p><h2 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h2><p>CC Switch v3.16.3（2026-06-14 发布）修复了这个问题。</p><h3 id="更新日志关键内容" tabindex="-1">更新日志关键内容 <a class="header-anchor" href="#更新日志关键内容" aria-label="Permalink to &quot;更新日志关键内容&quot;">​</a></h3><blockquote><p><strong>路由接管流量按真实上游模型计费</strong></p><p>当请求被路由到了不同的上游时，代理过去会按上游回显的模型来归因和计价...现在转发器会捕获真实的出站模型，按「上游回显 → 出站模型 → 客户端别名」的顺序归因，并在每行持久化实际使用的定价依据（schema v11）。</p></blockquote><blockquote><p><strong>PR #2774</strong>：修复 Completions 转 Anthropic 时不记录实际返回模型、input token 计算错误。</p></blockquote><h3 id="升级方法" tabindex="-1">升级方法 <a class="header-anchor" href="#升级方法" aria-label="Permalink to &quot;升级方法&quot;">​</a></h3><ol><li>从 <a href="https://github.com/farion1231/cc-switch/releases/latest" target="_blank" rel="noreferrer">GitHub Releases</a> 下载 v3.16.3 的 MSI 安装包</li><li>安装后重启 CC Switch</li><li>发一个请求验证</li></ol><h3 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h3><p>升级后查数据库：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">SELECT</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> model, request_model </span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">FROM</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> proxy_request_logs </span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">WHERE</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> app_type</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">=</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&#39;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">claude</span><span style="--shiki-light:#B5695977;--shiki-dark:#C98A7D77;">&#39;</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;"> ORDER BY</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> created_at </span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">DESC</span><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;"> LIMIT</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 5</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">;</span></span></code></pre></div><p>应该能看到：</p><table tabindex="0"><thead><tr><th>model</th><th>request_model</th></tr></thead><tbody><tr><td>qwen3.7-max</td><td>claude-opus-4-8</td></tr></tbody></table><p><code>model</code> 变成了实际转发的 <code>qwen3.7-max</code>，<code>request_model</code> 保留了 Claude Code 发来的 <code>claude-opus-4-8</code>。</p><h2 id="关键文件路径" tabindex="-1">关键文件路径 <a class="header-anchor" href="#关键文件路径" aria-label="Permalink to &quot;关键文件路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>说明</th></tr></thead><tbody><tr><td><code>~/.cc-switch/cc-switch.db</code></td><td>SQLite 数据库，<code>proxy_request_logs</code> 表存请求日志</td></tr><tr><td><code>~/.cc-switch/logs/cc-switch.log</code></td><td>CC Switch 运行日志</td></tr><tr><td><code>~/.cc-switch/settings.json</code></td><td>全局设置</td></tr></tbody></table><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><ul><li>问题出在 CC Switch 的格式转换路径（OpenAI → Anthropic）上，model 提取逻辑有 bug</li><li>不是代理的问题，代理响应完全正确</li><li>升级到 CC Switch v3.16.3 即可解决</li><li>其他中转站用 Anthropic 原生格式不受影响，只有用 OpenAI Chat Completions 格式的自建代理会遇到</li></ul>`,47)])])}const g=i(h,[["render",l]]);export{c as __pageData,g as default};
